import './galaxy.css';
import './research.css';
import {tasks,taskById,taskMatch,discover,recordedDegrees,sameDomainPeers,shortlistToggle,type DiscoveryTask,type DiscoverySort} from './discovery';
import {buildProjectReport,comparisonFacts,reportMarkup,reportMarkdown,reportHTML,type ResearchContext,type ProjectReport} from './report';
import {esc,safeUrl,type Lang} from '../observatory/model';
import {GalaxyScene} from './scene';
import {buildIndex,validGraph,filteredNodes,connectedNodes,allowedLink,categoryLabel,kindLabels,relationLabels,findByUrl,scopeDate} from './model';
import type {GalaxyGraph,GalaxySource,GalaxyIndex,GalaxyFilter,GalaxyCamera,GalaxyItem} from './types';

type Context=ResearchContext&{light:boolean;layout:string};
type Actions={modal:(title:string,body:string)=>void;toast:(s:string)=>void};
type State=GalaxyFilter&{selected:string;expanded:boolean;railOpen:boolean;tab:'relations'|'peers'|'metrics'|'participate';task:DiscoveryTask;sort:DiscoverySort;nearOnly:boolean;motion:boolean;path:{nodes:number[];edges:number[]}|null;trail:string[];camera?:GalaxyCamera;listPage:number};
const state:State={mode:'all',category:'',kind:'all',query:'',inferred:false,relation:'all',watchedOnly:false,selected:'',expanded:false,railOpen:!matchMedia('(max-width:650px)').matches,tab:'relations',task:'all',sort:'relevance',nearOnly:false,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,path:null,trail:[],listPage:0};
const graphs:Partial<Record<GalaxySource,GalaxyGraph>>={},pending:Partial<Record<GalaxySource,Promise<void>>>={},errors:Partial<Record<GalaxySource,string>>={};
let watched=new Set<string>();try{const a=JSON.parse(localStorage.getItem('od:galaxy-watch')??'[]');if(Array.isArray(a))watched=new Set(a.filter(x=>typeof x==='string'));}catch{}
let shortlist:string[]=[];try{const v=JSON.parse(localStorage.getItem('od:galaxy-shortlist')??'[]');if(Array.isArray(v))shortlist=[...new Set(v.filter(x=>typeof x==='string'&&x.length<500))].slice(0,3);}catch{}
let pendingUrl='';
export function locateGalaxy(url:string){pendingUrl=url;state.task='all';state.language='';state.nearOnly=false;state.path=null;state.mode='all';state.trail=[];state.query='';state.category='';state.kind='all';state.relation='all';state.watchedOnly=false;state.selected='';state.camera=undefined;}
const tx=(c:Context,z:string,e:string)=>c.lang==='zh'?z:e;
const num=(v:number|undefined,c:Context)=>v===undefined?'—':new Intl.NumberFormat(c.lang==='zh'?'zh-CN':'en',{maximumFractionDigits:1,notation:v>=100000?'compact':'standard'}).format(v);
const kind=(n:GalaxyItem,c:Context)=>(kindLabels[n.kind]??[n.kind,n.kind])[c.lang==='zh'?0:1];
const rel=(s:string,c:Context)=>(relationLabels[s]??[s,s])[c.lang==='zh'?0:1];
const ext=(url:string,title:string,cls='')=>`<a class="${cls}" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${title} ↗</a>`;
const short=(name:string)=>name.split('/').at(-1)!;
async function load(source:GalaxySource){
 if(graphs[source])return;if(pending[source])return pending[source];
 pending[source]=(async()=>{try{delete errors[source];const r=await fetch(`${import.meta.env.BASE_URL}data/galaxy/${source}.json`);if(!r.ok)throw Error(String(r.status));const g:unknown=await r.json();if(!validGraph(g))throw Error('Invalid graph');graphs[source]=g;}catch(e){errors[source]=String(e);}finally{delete pending[source];}})();return pending[source];
}
export function galaxyPage(c:Context){return `<main class="galaxy-page portal-page" aria-label="${tx(c,'开源星系','Open Galaxy')}"><div class="galaxy-loading" role="status"><span class="galaxy-loading-orbit" aria-hidden="true"></span><h1>${tx(c,'正在展开开源星系','Unfolding the open-source universe')}</h1><p>${tx(c,'加载真实项目与模型网络快照','Loading real project and model network snapshots')}</p></div></main>`;}

export function mountGalaxy(root:HTMLElement,c:Context,a:Actions):()=>void{
 let disposed=false,index:GalaxyIndex,scene:GalaxyScene|undefined,visible:number[]=[],matches:number[]=[],selected=-1,tourTimer:ReturnType<typeof setTimeout>|undefined,tourIndex=0,searchTimer:ReturnType<typeof setTimeout>|undefined,screenFocus:HTMLElement|null=null;
 const abort=new AbortController(),signal=abort.signal;let exportUrls:string[]=[];const clearExports=()=>{exportUrls.forEach(URL.revokeObjectURL);exportUrls=[];};
 const $=<T extends HTMLElement=HTMLElement>(s:string)=>root.querySelector<T>(s)!;
 function selectKey(i:number,focus=true,fromTour=false){if(!index.nodes[i])return;if(!fromTour)stopTour();state.path=null;state.nearOnly=false;if(!visible.includes(i)){state.mode=index.nodes[i].source;state.category='';state.kind='all';state.language='';state.task='all';state.watchedOnly=false;}selected=i;const n=index.nodes[i];state.selected=n.key;state.trail=[...state.trail.filter(x=>x!==n.key),n.key].slice(-5);state.tab='relations';root.classList.add('has-selection');updateDetail();updateTrail();updateControls();updateData();if(focus)scene?.focus([i]);history.replaceState(null,'',`#ecosystem?node=${encodeURIComponent(n.key)}`);}
 function reset(){stopTour();state.task='all';state.language='';state.nearOnly=false;state.path=null;state.category='';state.query='';state.kind='all';state.relation='all';state.watchedOnly=false;state.selected='';state.trail=[];state.listPage=0;selected=-1;root.classList.remove('has-selection');history.replaceState(null,'','#ecosystem');updateControls();updateData();scene?.fit();}
 function sceneOptions(){return{filter:state,visible,selected,highlights:state.query?matches.slice(0,80):[],path:state.path,motion:state.motion,light:c.light,lang:c.lang,camera:state.camera,onSelect:(i:number)=>selectKey(i,false),onInteract:stopTour,onCamera:(cam:GalaxyCamera)=>{state.camera=cam;const el=root.querySelector('.galaxy-magnification');if(el)el.textContent=`${cam.zoom.toFixed(1)}×`;},onHover:(i:number,x:number,y:number)=>{const box=$('#galaxy-hover');box.hidden=i<0;if(i<0)return;const n=index.nodes[i];box.innerHTML=`<strong>${esc(n.name)}</strong><span>${esc(kind(n,c))} · ${esc(categoryLabel(n.category,c.lang))}</span>`;box.style.left=`${Math.max(8,Math.min(x+15,$('.galaxy-stage').clientWidth-270))}px`;box.style.top=`${Math.max(8,y-65)}px`;}};}
 function updateData(){const candidates=filteredNodes(index,{...state,query:''},watched);visible=discover(index,candidates,state.task,'',state.sort);if(state.nearOnly&&selected>=0){const near=new Set([selected,...connectedNodes(index,selected,state).map(x=>x.node)]);visible=visible.filter(i=>near.has(i));}matches=discover(index,visible,state.task,state.query,state.sort);if(selected>=0&&!visible.includes(selected)){selected=-1;state.selected='';state.trail=[];history.replaceState(null,'','#ecosystem');root.classList.remove('has-selection');}scene?.update(sceneOptions());updateList();updateDetail();updateStatus();updateTrail();updateSecond();updateDock();updateWorkstate();}
 function title(source:GalaxySource){return source==='code'?tx(c,'代码星系','Code galaxy'):tx(c,'模型星系','Model galaxy');}
 function shell(){
  root.className=`galaxy-page portal-page ${state.expanded?'is-expanded':''} ${state.railOpen?'':'rail-closed'} ${c.layout==='two'?'galaxy-two':''} ${selected>=0?'has-selection':''}`;
  root.innerHTML=`<header class="galaxy-context"><div class="galaxy-title"><span class="galaxy-kicker">OPEN GALAXY</span><h1>${tx(c,'开源星系','The open-source universe')}</h1><p class="galaxy-purpose">${tx(c,'发现项目 · 理解连接 · 带走报告','Find projects · Trace connections · Take away a report')}</p></div><div class="galaxy-mode od-segmented" aria-label="${tx(c,'选择星系','Choose a galaxy')}">${[['all','星系全景','Universe'],['code','代码星系','Code'],['model','模型星系','Models']].map(([id,z,e])=>`<button data-galaxy-mode="${id}" aria-pressed="${state.mode===id}">${tx(c,z,e)}</button>`).join('')}</div><div class="galaxy-context-actions"><button class="galaxy-shortlist-open" data-galaxy-action="compare">${tx(c,'研究清单','Research list')} <b id="galaxy-shortlist-count">${shortlist.length}</b></button><button data-galaxy-action="guide">${tx(c,'探索指南','Guide')}</button><button data-galaxy-action="sources">${tx(c,'来源与口径','Sources & scope')}</button></div></header><div class="galaxy-load-notice" ${Object.keys(errors).length?'':'hidden'} role="status">${Object.keys(errors).map(x=>`${title(x as GalaxySource)} ${tx(c,'暂未加载','unavailable')}`).join(' · ')} <button data-galaxy-action="retry">${tx(c,'重试','Retry')}</button></div><div class="galaxy-body"><aside class="galaxy-rail"><div class="galaxy-rail-head"><b>${tx(c,'探索范围','EXPLORE')}</b><button data-galaxy-action="rail" aria-label="${tx(c,'收起探索栏','Collapse explorer')}">‹</button></div><label class="galaxy-search"><span aria-hidden="true">⌕</span><input id="galaxy-search" type="search" autocomplete="off" placeholder="${tx(c,'名称、用途、主题或语言…','Name, task, topic or language…')}" value="${esc(state.query)}" aria-label="${tx(c,'搜索星系节点','Search galaxy nodes')}"><kbd>/</kbd></label><label class="galaxy-task-label" for="galaxy-task">${tx(c,'我想做什么','WHAT ARE YOU BUILDING?')}</label><select id="galaxy-task">${tasks.map(x=>`<option value="${x.id}" ${x.id===state.task?'selected':''}>${tx(c,...x.name)}</option>`).join('')}</select><p class="galaxy-task-note" id="galaxy-task-note"></p><div class="galaxy-filter-fields"><label for="galaxy-category">${tx(c,'技术领域 / 任务','DOMAIN / TASK')}</label><select id="galaxy-category"></select><div class="galaxy-kind-filter" id="galaxy-kinds"></div><select id="galaxy-language" aria-label="${tx(c,'编程语言','Programming language')}"></select><details class="galaxy-advanced"><summary>${tx(c,'关系与关注筛选','Relations & following filters')}</summary><label for="galaxy-relation">${tx(c,'关系类型','RELATIONSHIP')}</label><select id="galaxy-relation"></select><label class="galaxy-check"><input id="galaxy-inferred" type="checkbox" ${state.inferred?'checked':''}>${tx(c,'包含推断关联','Include inferred links')}<span class="galaxy-inferred-dot"></span></label><label class="galaxy-check"><input id="galaxy-watched" type="checkbox" ${state.watchedOnly?'checked':''}>${tx(c,'仅我的关注','My watchlist')}</label></details></div><div class="galaxy-list-heading"><b id="galaxy-list-title">${tx(c,'发现项目','DISCOVER')}</b><button data-galaxy-action="reset">${tx(c,'重置','Reset')}</button></div><select id="galaxy-sort" aria-label="${tx(c,'结果排序','Sort results')}"><option value="relevance">${tx(c,'相关性与探索入口','Relevance & landmarks')}</option><option value="connections">${tx(c,'记录连接数','Recorded connections')}</option><option value="name">${tx(c,'名称 A–Z','Name A–Z')}</option></select><div class="galaxy-result-list" id="galaxy-result-list" aria-label="${tx(c,'可访问节点清单','Accessible node list')}"></div><div class="galaxy-pagination" id="galaxy-pagination"></div></aside><section class="galaxy-stage" aria-label="${tx(c,'可交互开源网络','Interactive open-source network')}"><canvas id="galaxy-canvas" tabindex="0" role="img" aria-label="${tx(c,'开源星系：拖动平移，滚轮或加减号缩放；方向键平移，Home 复位。也可从左侧清单选择节点。','Open galaxy. Drag to pan; wheel or plus/minus to zoom; arrow keys pan and Home resets. Select nodes from the accessible explorer list.')}" ></canvas><div class="galaxy-stage-caption"><span class="galaxy-stage-signal"></span><span id="galaxy-caption-label"></span><span class="galaxy-caption-count" id="galaxy-caption-count"></span></div><button class="galaxy-rail-reopen" data-galaxy-action="rail" aria-label="${tx(c,'展开探索栏','Open explorer')}">☰ ${tx(c,'探索','Explore')}</button><div class="galaxy-trail" id="galaxy-trail"></div><div class="galaxy-workstate" id="galaxy-workstate"></div><div class="galaxy-start" id="galaxy-start"></div><div class="galaxy-dock" id="galaxy-dock" hidden></div><div id="galaxy-hover" class="galaxy-hover" hidden></div><div class="galaxy-stage-tools"><button data-galaxy-action="zoom-in" aria-label="${tx(c,'放大星图','Zoom in')}">+</button><button data-galaxy-action="zoom-out" aria-label="${tx(c,'缩小星图','Zoom out')}">−</button><button data-galaxy-action="fit" title="${tx(c,'返回星系全景','Fit galaxy')}" aria-label="${tx(c,'返回星系全景','Fit galaxy')}">◎</button><button id="galaxy-expand" data-galaxy-action="expand" aria-pressed="${state.expanded}" aria-label="${tx(c,state.expanded?'退出星图全屏':'全屏星图',state.expanded?'Exit expanded galaxy':'Expand galaxy')}">${state.expanded?'↙':'⛶'}</button></div><div class="galaxy-tour-card" id="galaxy-tour-card" hidden aria-live="polite"></div><div class="galaxy-bottom"><div class="galaxy-legend"><span><i class="code"></i>${tx(c,'颜色：领域 / 任务','Color: domain / task')}</span><span>${tx(c,'大小：源内权重','Size: within-source weight')}</span><button data-galaxy-action="sources" aria-label="${tx(c,'查看图例口径','Explain the visual encoding')}">ⓘ</button></div><div class="galaxy-flight-controls"><button data-galaxy-action="motion" id="galaxy-motion" aria-pressed="${state.motion}" title="${tx(c,'视觉动效，不代表实时活动','Visual effects, not live activity')}">${tx(c,'动效','Motion')}</button><button data-galaxy-action="tour" id="galaxy-tour" aria-pressed="false">▷ ${tx(c,'星系巡游','Guided tour')}</button><button data-galaxy-action="expand" class="galaxy-return" ${state.expanded?'':'hidden'}>← ${tx(c,'返回','Return')} <kbd>Esc</kbd></button></div></div><div class="galaxy-no-results" hidden><h2>${tx(c,'这片星域暂时没有匹配目标','No matching targets in this field')}</h2><button data-galaxy-action="reset">${tx(c,'清除筛选','Clear filters')}</button></div></section><aside class="galaxy-inspector" id="galaxy-inspector" aria-label="${tx(c,'当前项目档案','Current entity profile')}"></aside></div><footer class="galaxy-status"><span id="galaxy-status-text" role="status"></span><span>${tx(c,'拖动探索 · 滚轮缩放 · 点击追踪关系','Drag to explore · Scroll to zoom · Select to trace relations')} <b class="galaxy-magnification">${(state.camera?.zoom??1).toFixed(1)}×</b></span></footer>${c.layout==='two'?`<section class="galaxy-second" id="galaxy-second"></section>`:''}`;
 }
 function updateControls(){
  $<HTMLSelectElement>('#galaxy-task').value=state.task;$<HTMLSelectElement>('#galaxy-sort').value=state.sort;$('#galaxy-task-note').textContent=tx(c,...taskById(state.task).description);
  const languages=[...new Set(index.nodes.filter(n=>n.source==='code'&&n.language&&n.language!=='Unknown').map(n=>n.language!))].sort();$('#galaxy-language').innerHTML=`<option value="">${tx(c,'全部编程语言','All programming languages')}</option>`+languages.map(x=>`<option ${state.language===x?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('');$('#galaxy-language').hidden=state.mode==='model';
  root.querySelectorAll<HTMLElement>('[data-galaxy-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.galaxyMode===state.mode)));
  $('#galaxy-search').setAttribute('value',state.query);($<HTMLInputElement>('#galaxy-search')).value=state.query;
  const categories=new Map<string,number>();index.nodes.filter(n=>state.mode==='all'||n.source===state.mode).forEach(n=>categories.set(n.category,(categories.get(n.category)??0)+1));
  $('#galaxy-category').innerHTML=`<option value="">${tx(c,'全部领域与任务','All domains & tasks')}</option>`+[...categories].sort((a,b)=>b[1]-a[1]).map(([id,count])=>`<option value="${esc(id)}" ${state.category===id?'selected':''}>${esc(categoryLabel(id,c.lang))} · ${num(count,c)}</option>`).join('');
  const kinds=[...new Set(index.nodes.filter(n=>state.mode==='all'||n.source===state.mode).map(n=>n.kind))];
  $('#galaxy-kinds').innerHTML=[['all',tx(c,'全部','All')],...kinds.map(k=>[k,(kindLabels[k]??[k,k])[c.lang==='zh'?0:1]])].map(([id,label])=>`<button data-galaxy-kind="${esc(id)}" aria-pressed="${state.kind===id}">${esc(label)}</button>`).join('');
  const relations=[...new Set(index.edges.filter(e=>state.mode==='all'||index.nodes[e.source].source===state.mode).filter(e=>state.inferred||!e.inferred).map(e=>e.kind))];
  $('#galaxy-relation').innerHTML=`<option value="all">${state.inferred?tx(c,'全部关系（含推断）','All links (including inferred)'):tx(c,'全部明确记录的关系','All recorded relationships')}</option>`+relations.map(k=>`<option value="${esc(k)}" ${state.relation===k?'selected':''}>${esc(rel(k,c))}</option>`).join('');
  $<HTMLInputElement>('#galaxy-inferred').checked=state.inferred;$<HTMLInputElement>('#galaxy-watched').checked=state.watchedOnly;
 }
 function updateList(){
  const pageSize=12,sorted=matches;state.listPage=Math.min(state.listPage,Math.max(0,Math.ceil(sorted.length/pageSize)-1));
  $('#galaxy-list-title').textContent=`${state.query?tx(c,'搜索结果','RESULTS'):tx(c,'探索入口','LANDMARKS')} · ${num(matches.length,c)}`;
  $('#galaxy-result-list').innerHTML=sorted.slice(state.listPage*pageSize,(state.listPage+1)*pageSize).map(i=>{const n=index.nodes[i];return `<button class="galaxy-result ${selected===i?'selected':''}" data-galaxy-node="${i}" aria-pressed="${selected===i}"><i style="--galaxy-node-color:var(--galaxy-c${n.colorIndex})"></i><span><strong>${esc(short(n.name))}</strong><small>${esc(n.name.split('/').slice(0,-1).join('/'))} · ${esc(kind(n,c))}</small><small class="galaxy-match-reason">${state.task!=='all'?tx(c,taskMatch(n,state.task).reason==='seed'?'精选探索入口':'任务元数据匹配',taskMatch(n,state.task).reason==='seed'?'Curated entry point':'Task metadata match'):n.language?esc(n.language):esc(categoryLabel(n.category,c.lang))}</small></span><b>↗</b></button>`;}).join('')||`<p class="galaxy-empty-list">${tx(c,'没有匹配节点，试试其他关键词。','No matching nodes. Try another search.')}</p>`;
  $('#galaxy-pagination').innerHTML=`<button data-galaxy-action="prev" ${state.listPage===0?'disabled':''} aria-label="${tx(c,'上一页项目','Previous nodes')}">←</button><span>${state.listPage+1} / ${Math.max(1,Math.ceil(sorted.length/pageSize))}</span><button data-galaxy-action="next" ${(state.listPage+1)*pageSize>=sorted.length?'disabled':''} aria-label="${tx(c,'下一页项目','Next nodes')}">→</button>`;
 }
 function resetForTask(){stopTour();state.category='';state.language='';state.kind='all';state.query='';state.nearOnly=false;state.path=null;state.watchedOnly=false;state.selected='';state.trail=[];state.listPage=0;selected=-1;root.classList.remove('has-selection');history.replaceState(null,'','#ecosystem');updateControls();updateData();scene?.focus(visible);}
 function updateWorkstate(){
  const active=state.task!=='all'||!!state.query||!!state.category||!!state.language||state.nearOnly||state.watchedOnly;
  const path=state.path;
  $('#galaxy-workstate').innerHTML=path?`<span class="galaxy-path-label">${tx(c,'记录关系路径','Recorded connection path')} · ${path.edges.length} ${tx(c,'步','hops')}</span><strong>${path.nodes.map(i=>esc(short(index.nodes[i].name))).join(' ↔ ')}</strong><button data-galaxy-action="clear-path" aria-label="${tx(c,'清除路径','Clear path')}">×</button>`:active?`<span>${state.nearOnly?tx(c,'关联子图','Neighborhood'):state.query?tx(c,'搜索定位','Search focus'):tx(c,...taskById(state.task).name)}</span><b>${num(matches.length,c)} ${tx(c,'个候选','candidates')}</b><button data-galaxy-action="reset">${tx(c,'清除筛选','Clear filters')}</button>`:'';
  $('#galaxy-workstate').hidden=!active&&!path;
  const start=$('#galaxy-start');start.hidden=selected>=0||active||!!path;
  start.innerHTML=`<span>${tx(c,'从一个问题开始','START WITH A QUESTION')}</span><h2>${tx(c,'找到你的下一颗星。','Find your next project.')}</h2><p>${tx(c,'选任务或搜索 → 探索关联 → 生成报告','Choose a task or search → Explore → Build a report')}</p><div>${tasks.slice(1).map(x=>`<button data-galaxy-task="${x.id}">${tx(c,...x.name)} ↗</button>`).join('')}</div>`;
 }
 function updateDock(){shortlist=shortlist.filter(k=>index.byKey.has(k));$('#galaxy-shortlist-count').textContent=String(shortlist.length);const dock=$('#galaxy-dock');dock.hidden=!shortlist.length;dock.innerHTML=`<span>${tx(c,'研究清单','RESEARCH LIST')} <b>${shortlist.length}/3</b></span>${shortlist.map(k=>`<div><button data-galaxy-node="${index.byKey.get(k)}">${esc(short(index.nodes[index.byKey.get(k)!].name))}</button><button data-galaxy-remove="${esc(k)}" aria-label="${tx(c,'移除','Remove')} ${esc(index.nodes[index.byKey.get(k)!].name)}">×</button></div>`).join('')}<button class="galaxy-dock-compare" data-galaxy-action="compare">${tx(c,'对照与研究','Compare & research')} ↗</button>`;root.classList.toggle('has-shortlist',!!shortlist.length);}
 function toggleShortlist(key:string){const result=shortlistToggle(shortlist,key,index);if(result.limited){a.toast(tx(c,'清单最多放 3 个对象，先移除一个再加入。','Keep up to three objects; remove one before adding another.'));return;}shortlist=result.keys;try{localStorage.setItem('od:galaxy-shortlist',JSON.stringify(shortlist));}catch{a.toast(tx(c,'清单仅保存在当前会话。','The list lasts for this session only.'));}updateDetail();updateDock();}
 function peersBody(n:GalaxyItem){return `<p class="galaxy-detail-intro">${tx(c,'同类型、同领域，优先共同主题。用于继续研究，功能是否可替代仍需验证。','Same type and domain, prioritizing shared topics. Explore further; functional equivalence is unverified.')}</p><div class="galaxy-neighbors">${sameDomainPeers(index,selected,8).map(x=>`<div class="galaxy-neighbor"><button data-galaxy-node="${x.i}"><strong>${esc(x.node.name)}</strong><span>${x.overlap?tx(c,`${x.overlap} 个共同主题`,`${x.overlap} shared topics`):esc(categoryLabel(x.node.category,c.lang))}</span></button></div>`).join('')||`<p class="galaxy-empty-list">${tx(c,'暂无同域样本','No same-domain sample')}</p>`}</div>`;}
 function openReport(id:number){clearExports();const r=buildProjectReport(index,id,c);a.modal(tx(c,'项目研究报告','Project research report'),`<div class="research-toolbar"><span>${tx(c,'证据汇编 · 可复现','EVIDENCE DOSSIER · REPRODUCIBLE')}</span><a data-research-export="md">Markdown ↓</a><a data-research-export="html">HTML ↓</a><a data-research-export="json">JSON ↓</a></div><nav class="research-nav">${[['summary','摘要','Brief'],['facts','指标','Metrics'],['network','生态','Network'],['checks','核验','Verify'],['sources','来源','Sources']].map(([id,z,e])=>`<button data-research-jump="research-${id}">${tx(c,z,e)}</button>`).join('')}</nav><p class="research-export-hint">${tx(c,'HTML 可离线打开并打印为 PDF；JSON 便于研究复用。','Open the HTML offline to print or save as PDF. JSON supports research reuse.')}</p>${reportMarkup(r)}`);
  const modal=document.querySelector<HTMLElement>('.modal')!;modal.classList.add('galaxy-research-modal');modal.querySelectorAll<HTMLAnchorElement>('[data-research-export]').forEach(b=>{const format=b.dataset.researchExport!,name=r.entity.name.replace(/[^a-z0-9._-]/gi,'-').slice(0,100),body=format==='json'?JSON.stringify(r,null,2):format==='html'?reportHTML(r):reportMarkdown(r),mime=format==='json'?'application/json':format==='html'?'text/html':'text/markdown';const url=URL.createObjectURL(new Blob([body],{type:`${mime};charset=utf-8`}));exportUrls.push(url);b.href=url;b.download=`OpenDipper-${name}-${r.generatedAt.slice(0,10)}.${format}`;});modal.querySelectorAll<HTMLElement>('[data-research-jump]').forEach(b=>b.onclick=()=>modal.querySelector('#'+b.dataset.researchJump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));
 }
 function openCompare(){
  const ids=shortlist.map(k=>index.byKey.get(k)).filter((i):i is number=>i!==undefined);if(!ids.length){a.modal(tx(c,'建立研究清单','Build your research list'),`<div class="galaxy-guide"><p>${tx(c,'先在星图或搜索结果中选择一个项目，点击“加入研究清单”。最多保留 3 个对象，进行指标对照、关系路径探索和报告生成。','Select a project from the galaxy or search results, then add it to your research list. Keep up to three objects to compare facts, trace recorded paths and generate reports.')}</p></div>`);return;}
  const ns=ids.map(i=>index.nodes[i]),comparison=comparisonFacts(index,ids),degrees=recordedDegrees(index),reports=ids.map(i=>buildProjectReport(index,i,c));
  const row=(label:string,values:string[])=>`<tr><th>${label}</th>${values.map(x=>`<td>${x}</td>`).join('')}</tr>`;
  const metricRows=comparison.sameType?(ns[0].source==='code'?[row(tx(c,'12 月累计 OpenRank','12-month OpenRank sum'),ns.map(n=>num(n.openrank,c))),row(tx(c,'贡献者','Contributors'),ns.map(n=>num(n.contributors,c)))]:[...(ns[0].kind==='space'?[]:[row(tx(c,'下载 · 图快照','Downloads · graph snapshot'),ns.map(n=>num(n.downloads,c)))]),row(tx(c,'点赞','Likes'),ns.map(n=>num(n.likes,c)))]).join(''):'';
  a.modal(tx(c,'研究清单 · 对照与连接','Research list · compare & connect'),`<div class="galaxy-comparison"><p>${comparison.sameType?tx(c,'同类对象、同一网络快照；指标用于对照，不代表质量排名。','Same entity type and network snapshot. Measures support comparison, not a quality ranking.'):tx(c,'这些对象属于不同类型，按组件清单并列展示；不同量纲不合成总分。','These are different entity types, shown as a component list. Unlike measures are not combined into a score.')}</p><div class="research-table-wrap"><table><thead><tr><th>${tx(c,'研究维度','Dimension')}</th>${ns.map(n=>`<th><span>${esc(n.name)}</span><button data-compare-remove="${esc(n.key)}" aria-label="${tx(c,'移除','Remove')} ${esc(n.name)}">×</button></th>`).join('')}</tr></thead><tbody>${row(tx(c,'类型 / 领域','Type / domain'),ns.map(n=>`${esc(kind(n,c))}<small>${esc(categoryLabel(n.category,c.lang))}</small>`))}${row(tx(c,'观察期','Observation'),ns.map(n=>scopeDate(index.graphs[n.source]!)))}${metricRows}${row(tx(c,'记录邻居','Recorded neighbors'),ids.map(i=>num(degrees[i],c)))}${row(tx(c,'许可元数据','License metadata'),reports.map(r=>esc(r.license?.value??tx(c,'待核验','Unverified'))))}${row(tx(c,'下一步','Next step'),ids.map(i=>`<button class="galaxy-report-primary" data-compare-report="${i}">${tx(c,'生成报告','Build report')} ↗</button>`))}</tbody></table></div>${ids.length>=2?`<section class="galaxy-path-form"><h3>${tx(c,'它们在生态中如何相连？','How are they connected?')}</h3><p>${tx(c,'寻找 3 步以内的记录关系；不使用推断边，不表示依赖链或技术适配。','Find a recorded path within three hops. Inferred edges are excluded; this is not a dependency chain or compatibility check.')}</p><div><select id="galaxy-path-from" aria-label="${tx(c,'路径起点','Path start')}">${ids.map(i=>`<option value="${i}">${esc(index.nodes[i].name)}</option>`).join('')}</select><span>↔</span><select id="galaxy-path-to" aria-label="${tx(c,'路径终点','Path end')}">${ids.map((i,j)=>`<option value="${i}" ${j===1?'selected':''}>${esc(index.nodes[i].name)}</option>`).join('')}</select><button id="galaxy-find-path">${tx(c,'在星图中追踪','Trace in the galaxy')} ↗</button></div><p id="galaxy-path-result" role="status"></p></section>`:''}<p class="galaxy-note">${tx(c,'清单保存在本机浏览器。许可为来源元数据，采用前请核对项目原文。','This list is local to this browser. License metadata requires verification against the original project.')}</p></div>`);
  const modal=document.querySelector<HTMLElement>('.modal')!;modal.classList.add('galaxy-comparison-modal');modal.querySelectorAll<HTMLElement>('[data-compare-remove]').forEach(b=>b.onclick=()=>{toggleShortlist(b.dataset.compareRemove!);openCompare();});modal.querySelectorAll<HTMLElement>('[data-compare-report]').forEach(b=>b.onclick=()=>openReport(Number(b.dataset.compareReport)));
  modal.querySelector<HTMLElement>('#galaxy-find-path')?.addEventListener('click',()=>{const from=Number(modal.querySelector<HTMLSelectElement>('#galaxy-path-from')!.value),to=Number(modal.querySelector<HTMLSelectElement>('#galaxy-path-to')!.value),path=comparisonFacts(index,[from,to]).path!;if(path.status!=='found'){modal.querySelector('#galaxy-path-result')!.textContent=path.status==='different-networks'?tx(c,'当前来源尚未提供跨星系关系，无法建立连接。','No cross-network relationships are provided by these sources.'):path.status==='same'?tx(c,'请选择两个不同对象。','Choose two different objects.'):tx(c,'当前快照内没有找到 3 步以内的记录路径，不表示现实中不存在关系。','No recorded path within three hops in this snapshot; this does not prove absence of a real-world relationship.');return;}document.querySelector<HTMLButtonElement>('#close-modal')?.click();state.mode=index.nodes[from].source;state.task='all';state.category='';state.language='';state.kind='all';state.query='';state.watchedOnly=false;state.nearOnly=false;state.relation='all';state.inferred=false;selectKey(from,false);state.path={nodes:path.nodes,edges:path.edges};updateControls();updateData();scene?.focus(path.nodes);});
 }

 function updateTrail(){ $('#galaxy-trail').innerHTML=state.trail.length?`<button data-galaxy-action="fit">${tx(c,'全景','Universe')}</button>`+state.trail.map(key=>{const i=index.byKey.get(key),n=i===undefined?undefined:index.nodes[i];return n?`<span>›</span><button data-galaxy-node="${i}" aria-current="${key===state.selected?'true':'false'}">${esc(short(n.name).slice(0,23))}</button>`:'';}).join(''):'';}
 function updateStatus(){let observed=0,inferred=0;const ids=new Set(visible);for(const e of index.edges)if(ids.has(e.source)&&ids.has(e.target)&&allowedLink(e,state)){if(e.inferred)inferred++;else observed++;}
  $('#galaxy-caption-label').textContent=state.inferred?tx(c,'网络快照 · 含推断关联','NETWORK SNAPSHOTS · INFERENCE ON'):tx(c,'真实网络快照','OBSERVED NETWORK SNAPSHOTS');
  $('#galaxy-caption-count').textContent=`${num(visible.length,c)} ${tx(c,'个节点','nodes')}`;
  $('#galaxy-status-text').textContent=`${num(observed,c)} ${tx(c,'条记录关系','recorded relations')}${state.inferred?` + ${num(inferred,c)} ${tx(c,'条推断','inferred')}`:''} · ${Object.entries(index.graphs).sort(([a],[b])=>a.localeCompare(b)).filter(([s])=>state.mode==='all'||s===state.mode).map(([s,g])=>`${title(s as GalaxySource)} ${scopeDate(g)}`).join(' / ')}`;
  $('.galaxy-no-results').hidden=visible.length>0;
 }
 function metricBody(n:GalaxyItem){const g=index.graphs[n.source]!;const rows=n.source==='code'? [[tx(c,'12 个月 OpenRank 累计','12-month OpenRank sum'),n.openrank],[tx(c,'贡献者','Contributors'),n.contributors]]:[[tx(c,'下载量 · 来源快照','Downloads · source snapshot'),n.downloads],[tx(c,'点赞','Likes'),n.likes]];
  if(n.kind==='space')rows.splice(0,1);
  const repo=c.repositories.find(r=>r.path?.toLowerCase()===n.name.toLowerCase()),points=repo?.metrics?.openrank?.points?.filter((p:any)=>typeof p.value==='number').slice(-12)??[];
  return `<div class="galaxy-metrics">${rows.map(([label,value])=>`<div><span>${label}</span><strong>${num(value as number|undefined,c)}</strong></div>`).join('')}</div><p class="galaxy-note">${esc(scopeDate(g))} · ${n.source==='code'?tx(c,'月度继承分数之和，不是重新计算的年度 OpenRank。','Sum of inherited monthly scores, not a recalculated annual OpenRank.'):tx(c,'下载与点赞不代表模型性能或独立使用人数。','Downloads and likes do not measure capability or unique users.')}</p>${points.length?`<h3>${tx(c,'月度影响力','Monthly influence')}</h3><div class="galaxy-monthly">${points.map((p:any)=>`<div><time>${esc(p.month)}</time><meter min="0" max="${Math.max(...points.map((x:any)=>x.value),1)}" value="${p.value}" aria-label="${esc(p.month)} OpenRank ${p.value}"></meter><span>${num(p.value,c)}</span></div>`).join('')}</div>`:`<div class="galaxy-detail-empty">${tx(c,'当前网络快照未包含连续月度趋势，后续可接入 OpenDigger 历史序列。','This network snapshot has no monthly series. OpenDigger history can be connected later.')}</div>`}`;
 }
 function updateDetail(){
  const box=$('#galaxy-inspector');if(selected<0){box.innerHTML='';return;}const n=index.nodes[selected],connections=connectedNodes(index,selected,state),visibleIds=new Set(visible),visibleLinks=connections.filter(x=>visibleIds.has(x.node)),observed=new Set(visibleLinks.filter(x=>!x.edge.inferred).map(x=>x.node)).size;
  const body=state.tab==='relations'?`<div class="galaxy-relations-summary"><strong>${num(observed,c)}</strong><span>${tx(c,'个记录关联节点','recorded neighbors')}</span><button data-galaxy-action="neighborhood">${tx(c,state.nearOnly?'恢复全景背景':'只看关联',state.nearOnly?'Restore context':'Isolate neighbors')} ↗</button></div><div class="galaxy-neighbors">${visibleLinks.slice(0,16).map(({node,edge,edgeIndex})=>`<div class="galaxy-neighbor"><button data-galaxy-node="${node}"><strong>${esc(short(index.nodes[node].name))}</strong><span>${esc(rel(edge.kind,c))}${edge.shared!==null&&n.source==='code'?` · ${num(edge.shared,c)} ${tx(c,'人','people')}`:''}</span></button><button class="galaxy-edge-info" data-galaxy-edge="${edgeIndex}" aria-label="${tx(c,'解释关系','Explain relationship')}">ⓘ</button></div>`).join('')||`<p class="galaxy-detail-empty">${tx(c,'当前筛选下没有记录的邻居。可以调整关系类型或探索领域。','No recorded neighbors under these filters. Adjust the relationship or domain.')}</p>`}</div>${visibleLinks.length>16?`<p class="galaxy-note">${tx(c,`展示最强的 16 个关联，共 ${visibleLinks.length} 个；星图保留全部匹配节点。`,`Showing 16 strongest of ${visibleLinks.length} neighbors; matching nodes remain on the map.`)}</p>`:''}`:state.tab==='peers'?peersBody(n):state.tab==='metrics'?metricBody(n):`<div class="galaxy-participate"><h3>${tx(c,'从了解，到参与','From discovery to participation')}</h3><p>${tx(c,'先阅读项目说明和参与规范，再选择一个与你相关的任务。','Read the project description and contribution guidance, then choose a relevant task.')}</p>${ext(n.url,tx(c,'打开官方项目','Open official project'),'galaxy-primary')}${n.source==='code'?ext(n.url.replace(/\/$/,'')+'/issues',tx(c,'查看议题与贡献机会','Explore issues & contribution opportunities')):ext(n.url.replace(/\/$/,'')+'/discussions',tx(c,'进入社区讨论','Open community discussions'))}<button data-galaxy-action="watch">${watched.has(n.key)?'★':'☆'} ${tx(c,watched.has(n.key)?'已关注 · 点击取消':'关注这个项目',watched.has(n.key)?'Following · remove':'Follow this project')}</button><p class="galaxy-note">${tx(c,'关注保存在当前浏览器，尚无自动通知。','Following is local to this browser; automated alerts are not available.')}</p></div>`;
  box.innerHTML=`<header class="galaxy-inspector-head"><span>${tx(c,'当前观察','CURRENT TARGET')}</span><button data-galaxy-action="close" aria-label="${tx(c,'关闭项目档案','Close profile')}">×</button></header><div class="galaxy-profile"><span class="galaxy-entity-kind">${esc(kind(n,c))} / ${esc(categoryLabel(n.category,c.lang))}</span><h2>${esc(short(n.name))}</h2><p class="galaxy-entity-id">${esc(n.name)}</p>${n.description?`<p class="galaxy-description">${esc(n.description)}</p>`:''}</div><div class="galaxy-research-actions"><button class="galaxy-report-primary" data-galaxy-action="report">${tx(c,'生成项目报告','Build project report')} ↗</button><button data-galaxy-action="shortlist" aria-pressed="${shortlist.includes(n.key)}">${tx(c,shortlist.includes(n.key)?'已加入清单':'＋ 加入研究清单',shortlist.includes(n.key)?'In research list':'+ Add to research list')}</button></div><div class="galaxy-detail-tabs" role="tablist" aria-label="${tx(c,'项目详情','Entity details')}">${[['relations','关系','Relations'],['peers','同域','Peers'],['metrics','指标','Metrics'],['participate','参与','Participate']].map(([id,z,en])=>`<button role="tab" id="galaxy-tab-${id}" data-galaxy-tab="${id}" aria-selected="${state.tab===id}" aria-controls="galaxy-detail-body" tabindex="${state.tab===id?0:-1}">${tx(c,z,en)}</button>`).join('')}</div><div class="galaxy-detail-body" id="galaxy-detail-body" role="tabpanel" aria-labelledby="galaxy-tab-${state.tab}">${body}</div><footer class="galaxy-inspector-footer"><button data-galaxy-action="watch" aria-pressed="${watched.has(n.key)}">${watched.has(n.key)?'★':'☆'} ${tx(c,watched.has(n.key)?'已关注':'关注',watched.has(n.key)?'Following':'Follow')}</button><button data-galaxy-action="share">${tx(c,'复制位置','Copy position')}</button>${ext(n.url,tx(c,'项目主页','Project page'))}</footer>`;
 }
 function updateSecond(){const el=root.querySelector('#galaxy-second');if(!el)return;el.innerHTML=`<header><span>02 / EXPLORATION LOG</span><h2>${tx(c,'继续探索你的星域','Explore your field further')}</h2><p>${tx(c,'与上方星图使用同一组筛选，点击项目回到其生态位置。','Uses the same filters as the galaxy. Select a project to locate its ecosystem position.')}</p></header><div>${visible.slice().sort((a,b)=>index.nodes[b].score-index.nodes[a].score).slice(0,24).map(i=>`<button data-galaxy-node="${i}"><span>${esc(kind(index.nodes[i],c))}</span><strong>${esc(index.nodes[i].name)}</strong><small>${esc(categoryLabel(index.nodes[i].category,c.lang))}</small></button>`).join('')}</div>`;}
 function guide(){a.modal(tx(c,'探索开源星系','Explore the open-source universe'),`<div class="galaxy-guide"><p>${tx(c,'从任务出发，找到候选，理解它的位置，带走一份有来源的研究报告。','Start with a task, find candidates, understand their ecosystem and take away a sourced research report.')}</p><ol><li><b>${tx(c,'发现','Discover')}</b> — ${tx(c,'选择“我想做什么”，或搜索名称、主题、语言。探索入口和元数据匹配都会说明入选理由。','Choose a task or search a name, topic or language. Results distinguish curated entry points from metadata matches.')}</li><li><b>${tx(c,'定位','Locate')}</b> — ${tx(c,'搜索名称后选择清单中的节点；滚轮缩放，拖动平移。键盘方向键、+ / −、Home 同样可用。','Search a name and select a result. Scroll to zoom and drag to pan. Arrow keys, + / − and Home also work.')}</li><li><b>${tx(c,'理解','Understand')}</b> — ${tx(c,'点击节点照亮直接邻居，点击关系说明核对为什么相连。','Select a node to highlight its neighbors; open relationship explanations to understand each connection.')}</li><li><b>${tx(c,'参与','Participate')}</b> — ${tx(c,'加入最多 3 个研究对象，对照同类指标或查看组件组合；追踪最多 3 跳的记录关系，再生成项目报告。','Shortlist up to three objects, compare like-for-like metrics or inspect a component collection; trace up to three recorded hops, then build a report.')}</li></ol><h3>${tx(c,'报告能回答什么','What the report answers')}</h3><p>${tx(c,'汇总身份、已知许可、独立时间口径的指标、关系与同域候选、已收录动态及核验清单。未知项保持未知，不代替实际评测。可导出 Markdown、HTML 和 JSON；HTML 可离线打印为 PDF。清单与关注只保存在当前浏览器。','Reports assemble identity, known license, dated metrics, relationships, peers, collected updates and a verification checklist. Unknowns stay unknown; this is not a benchmark. Export Markdown, HTML or JSON; print the HTML to PDF offline. Lists and follows stay in this browser.')}</p><h3>${tx(c,'如何读图','Read the galaxy')}</h3><p>${tx(c,'位置来自上游预计算网络布局；颜色表示技术领域或模型任务。代码节点大小按 12 个月 OpenRank 累计值压缩映射；模型节点使用上游展示权重，不能与代码节点比较。全景中两个星系分别归一化。柔和星云表示节点聚集，不是额外数据。','Positions follow the upstream precomputed network layout. Colors represent domains or model tasks. Code node size compresses 12-month OpenRank sums; model size uses the upstream display weight and cannot be compared with code sizes. Each galaxy is normalized separately. Nebula shading shows concentration, not extra entities.')}</p><p>${tx(c,'巡游仅为镜头导览，不表示实时事件。手动操作或 Esc 会停止巡游；减少动态设置下使用即时定位。','The tour is camera navigation, not live activity. Interaction or Escape stops it; reduced-motion uses instant positioning.')}</p></div>`);}
 function sources(){a.modal(tx(c,'开源星系 · 来源与口径','Open Galaxy · sources & scope'),`<div class="galaxy-source-dialog"><p>${tx(c,'这是两个有范围的网络快照，不代表全球全部开源资产。','These are two scoped network snapshots, not all open-source assets worldwide.')}</p>${Object.entries(index.graphs).sort(([a],[b])=>a.localeCompare(b)).map(([id,g])=>`<section><h3>${title(id as GalaxySource)}</h3><p>${num(g.nodes.length,c)} ${tx(c,'个节点','nodes')} · ${num(g.edges.length,c)} ${tx(c,'条来源边','source edges')} · ${esc(scopeDate(g))}</p><p>${id==='code'?tx(c,'节点是经 OpenRank 筛选并保留连接的 GitHub 仓库；边表示共享已知非 Bot 贡献者的亲和关系，不是代码依赖，也不证明双方直接合作。','Nodes are OpenRank-selected GitHub repositories retained after edge filtering. Edges reflect shared known non-bot contributors, not code dependencies or proof of direct cooperation.'):tx(c,'模型、数据集和 Space 为来源选取样本。实线关系来自元数据；同一发布账号不代表同一法律主体。任务相近等推断关系默认关闭，开启后以虚线显示。来源将端点排序，不能据此画出派生方向。','Models, datasets and Spaces are source-selected samples. Recorded relationships come from metadata; a shared publishing account is not a verified legal organization. Inferred task/taxonomy links are off by default and dashed when enabled. Endpoints were sorted upstream, so lineage direction cannot be recovered from this export.')}</p>${ext(g.meta.upstreamUrl,tx(c,'固定版本数据来源','Pinned data source'))}<small>${esc(g.meta.sourceCommit)}</small></section>`).join('')}<p>${tx(c,'坐标与节点身份来自同一个固定版本；当前没有历史网络帧和跨星系关系，因而没有补造演化或桥梁。','Coordinates and identities come from the same pinned version. Historical graph frames and cross-galaxy relations are not available; neither is fabricated.')}</p>${ext('https://github.com/YaoYao-Pig/OG-And-HG-2026',tx(c,'OpenGalaxy / ModelGalaxy 原项目','Original OpenGalaxy / ModelGalaxy project'))}</div>`);}
 function explainEdge(i:number){const e=index.edges[i];if(!e)return;const s=index.nodes[e.source],t=index.nodes[e.target];a.modal(rel(e.kind,c),`<div class="galaxy-edge-dialog"><h3>${esc(s.name)}</h3><p>↔</p><h3>${esc(t.name)}</h3><p>${e.inferred?tx(c,'这是一条由任务或分类规则推断的探索关联，不是已验证的依赖、派生或合作。','This exploratory association is inferred from task/taxonomy rules, not verified dependency, lineage or collaboration.'):e.kind==='shared-contributors'?tx(c,`两端仓库在来源周期内有 ${e.shared??'—'} 位符合筛选条件的共享贡献者。`,`These repositories share ${e.shared??'—'} contributors meeting the source filters during the observation period.`):e.kind==='same-author'?tx(c,'来源记录的发布账号相同，不表示已核验企业归属。','The source records the same publisher account, not verified company ownership.'):tx(c,'来源元数据记录了这类关联；当前导出未保留可恢复的方向，故按无向关系展示。','Source metadata records this relationship. The export does not preserve recoverable direction, so it is shown undirected.')}</p>${ext(index.graphs[s.source]!.meta.upstreamUrl,tx(c,'查看来源','View source'))}</div>`);}
 function stopTour(){if(tourTimer)clearTimeout(tourTimer);tourTimer=undefined;root.querySelector('#galaxy-tour')?.setAttribute('aria-pressed','false');const b=root.querySelector('#galaxy-tour');if(b)b.textContent=`▷ ${tx(c,'星系巡游','Guided tour')}`;const card=root.querySelector<HTMLElement>('#galaxy-tour-card');if(card)card.hidden=true;}
 function tour(){if(tourTimer){stopTour();return;}state.mode='all';state.task='all';state.language='';state.nearOnly=false;state.path=null;state.category='';state.kind='all';state.query='';state.relation='all';state.watchedOnly=false;updateControls();updateData();
  const landmarks=['pytorch/pytorch','kubernetes/kubernetes','microsoft/vscode','NixOS/nixpkgs','sentence-transformers/all-MiniLM-L6-v2','BAAI/bge-m3'];const ids=landmarks.map(name=>index.nodes.findIndex(n=>n.name===name)).filter(i=>i>=0);if(!ids.length){a.toast(tx(c,'没有可用的巡游目标','No tour targets available'));return;}
  const step=()=>{if(disposed||document.hidden){stopTour();return;}const i=ids[tourIndex%ids.length],n=index.nodes[i];tourIndex++;selectKey(i,false,true);const neighbors=connectedNodes(index,i,state).slice(0,50).map(x=>x.node);scene?.focus([i,...neighbors]);const card=$('#galaxy-tour-card');card.hidden=false;card.innerHTML=`<span>${String((tourIndex-1)%ids.length+1).padStart(2,'0')} / ${String(ids.length).padStart(2,'0')} · ${tx(c,'星系巡游','GUIDED TOUR')}</span><strong>${esc(n.name)}</strong><p>${esc(categoryLabel(n.category,c.lang))} · ${tx(c,'查看它连接的项目与社区','Explore its connected projects and communities')}</p>`;$('#galaxy-tour').textContent=`Ⅱ ${tx(c,'停止巡游','Stop tour')}`;$('#galaxy-tour').setAttribute('aria-pressed','true');tourTimer=setTimeout(step,6500);};step();
 }
 function expanded(){stopTour();state.expanded=!state.expanded;if(state.expanded){screenFocus=document.activeElement as HTMLElement;document.body.classList.add('galaxy-fullscreen');}else document.body.classList.remove('galaxy-fullscreen');root.classList.toggle('is-expanded',state.expanded);$('#galaxy-expand').textContent=state.expanded?'↙':'⛶';$('#galaxy-expand').setAttribute('aria-pressed',String(state.expanded));$('#galaxy-expand').setAttribute('aria-label',tx(c,state.expanded?'退出星图全屏':'全屏星图',state.expanded?'Exit expanded galaxy':'Expand galaxy'));$('.galaxy-return').hidden=!state.expanded;document.querySelectorAll<HTMLElement>('.galaxy-shell > .topbar').forEach(x=>x.inert=state.expanded);if(state.expanded)$('#galaxy-expand').focus();else screenFocus?.isConnected&&screenFocus.focus();}
 async function init(){await Promise.allSettled([load('code'),load('model')]);if(disposed)return;index=buildIndex(graphs);if(!index.nodes.length){root.innerHTML=`<div class="galaxy-loading"><h1>${tx(c,'星系快照暂不可用','Galaxy snapshots unavailable')}</h1><p>${tx(c,'请重试；其他模块仍可正常使用。','Please retry. Other modules remain available.')}</p><button data-galaxy-action="retry">${tx(c,'重试','Retry')}</button></div>`;return;}
  const hash=new URLSearchParams(location.hash.split('?')[1]??'');if(hash.get('node')&&!pendingUrl)state.selected=hash.get('node')!;
  selected=index.byKey.get(state.selected)??-1;let focusAfter=false;if(pendingUrl){const i=findByUrl(index,pendingUrl);if(i>=0){selected=i;state.selected=index.nodes[i].key;state.mode=index.nodes[i].source;focusAfter=true;}else{state.query=pendingUrl.split('/').at(-1)??'';a.toast(tx(c,'这个实体尚未纳入当前星图样本，已按名称搜索。','This entity is outside the current graph sample; searching its name instead.'));}pendingUrl='';}
  if(state.selected&&selected>=0){if(state.mode!=='all'&&state.mode!==index.nodes[selected].source)state.mode=index.nodes[selected].source;state.trail=state.trail.length?state.trail:[state.selected];focusAfter=!state.camera;history.replaceState(null,'',`#ecosystem?node=${encodeURIComponent(state.selected)}`);}
  shell();updateControls();updateData();try{scene=new GalaxyScene($<HTMLCanvasElement>('#galaxy-canvas'),index,sceneOptions());if(focusAfter)scene.focus([selected],false);else if(!state.camera&&state.mode!=='all')scene.fit();}catch{a.toast(tx(c,'当前浏览器无法绘制星图，可继续使用左侧项目清单。','The canvas is unavailable; use the accessible node list.'));}
  if(state.expanded){document.body.classList.add('galaxy-fullscreen');document.querySelectorAll<HTMLElement>('.galaxy-shell > .topbar').forEach(x=>x.inert=true);}
 }
 root.addEventListener('click',async event=>{const b=(event.target as HTMLElement).closest<HTMLElement>('button,a');if(!b)return;
  if(b.dataset.galaxyTask){state.task=b.dataset.galaxyTask as DiscoveryTask;state.mode='all';resetForTask();return;}
  if(b.dataset.galaxyRemove){toggleShortlist(b.dataset.galaxyRemove);return;}
  if(b.dataset.galaxyMode){stopTour();state.task='all';state.language='';state.nearOnly=false;state.path=null;state.mode=b.dataset.galaxyMode as State['mode'];state.category='';state.kind='all';state.relation='all';state.query='';state.listPage=0;state.selected='';state.trail=[];selected=-1;history.replaceState(null,'','#ecosystem');root.classList.remove('has-selection');updateControls();updateData();scene?.fit();return;}
  if(b.dataset.galaxyKind){stopTour();state.path=null;state.kind=b.dataset.galaxyKind;state.listPage=0;updateControls();updateData();return;}
  if(b.dataset.galaxyNode){selectKey(Number(b.dataset.galaxyNode));updateList();if(b.closest('.galaxy-second'))root.scrollIntoView({behavior:'smooth'});return;}
  if(b.dataset.galaxyEdge){stopTour();explainEdge(Number(b.dataset.galaxyEdge));return;}
  if(b.dataset.galaxyTab){stopTour();state.tab=b.dataset.galaxyTab as State['tab'];updateDetail();$(`#galaxy-tab-${state.tab}`).focus({preventScroll:true});return;}
  const action=b.dataset.galaxyAction;if(!action)return;if(action!=='tour')stopTour();
  if(action==='retry'){scene?.destroy();scene=undefined;await init();}
  else if(action==='reset')reset();else if(action==='fit'){state.nearOnly=false;state.path=null;state.selected='';selected=-1;root.classList.remove('has-selection');history.replaceState(null,'','#ecosystem');updateData();scene?.fit();}
  else if(action==='zoom-in')scene?.zoom(1.35);else if(action==='zoom-out')scene?.zoom(.75);
  else if(action==='rail'){state.railOpen=!state.railOpen;root.classList.toggle('rail-closed',!state.railOpen);if(state.railOpen)$<HTMLInputElement>('#galaxy-search').focus();else $('.galaxy-rail-reopen').focus();}
  else if(action==='guide')guide();else if(action==='sources')sources();else if(action==='tour')tour();else if(action==='expand')expanded();
  else if(action==='prev'||action==='next'){state.listPage+=action==='next'?1:-1;updateList();}
  else if(action==='close'){state.nearOnly=false;state.path=null;selected=-1;state.selected='';root.classList.remove('has-selection');history.replaceState(null,'','#ecosystem');updateData();$('#galaxy-canvas').focus();}
  else if(action==='neighborhood'&&selected>=0){state.nearOnly=!state.nearOnly;updateData();scene?.focus(state.nearOnly?visible:[selected,...connectedNodes(index,selected,state).map(x=>x.node).filter(i=>visible.includes(i))]);}
  else if(action==='report'&&selected>=0)openReport(selected);else if(action==='shortlist'&&selected>=0)toggleShortlist(index.nodes[selected].key);else if(action==='compare')openCompare();
  else if(action==='motion'){state.motion=!state.motion;$('#galaxy-motion').setAttribute('aria-pressed',String(state.motion));scene?.update({motion:state.motion});}
  else if(action==='clear-path'){state.path=null;updateData();}
  else if(action==='watch'&&selected>=0){const key=index.nodes[selected].key;watched.has(key)?watched.delete(key):watched.add(key);try{localStorage.setItem('od:galaxy-watch',JSON.stringify([...watched]));}catch{a.toast(tx(c,'浏览器存储不可用，关注仅保留在当前会话。','Storage unavailable; following lasts for this session.'));}updateData();}
  else if(action==='share'&&selected>=0){try{await navigator.clipboard.writeText(location.href);a.toast(tx(c,'已复制星图位置','Galaxy position copied'));}catch{a.modal(tx(c,'分享星图位置','Share galaxy position'),`<p>${esc(location.href)}</p>`);}}
 },{signal});
 root.addEventListener('input',e=>{if((e.target as HTMLElement).id!=='galaxy-search')return;stopTour();state.query=(e.target as HTMLInputElement).value;state.listPage=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(!disposed){updateData();if(matches.length&&matches.length<80)scene?.focus(matches);}},140);},{signal});
 root.addEventListener('change',e=>{stopTour();state.path=null;const el=e.target as HTMLInputElement;state.listPage=0;if(el.id==='galaxy-task'){state.task=el.value as DiscoveryTask;state.mode='all';resetForTask();return;}else if(el.id==='galaxy-language')state.language=el.value;else if(el.id==='galaxy-sort')state.sort=el.value as DiscoverySort;else if(el.id==='galaxy-category')state.category=el.value;else if(el.id==='galaxy-relation')state.relation=el.value;else if(el.id==='galaxy-inferred'){state.inferred=el.checked;state.relation='all';}else if(el.id==='galaxy-watched')state.watchedOnly=el.checked;updateControls();updateData();if(el.id==='galaxy-category'&&visible.length)scene?.focus(visible);},{signal});
 root.addEventListener('keydown',e=>{const target=e.target as HTMLElement;if(target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['relations','peers','metrics','participate'] as const,i=tabs.indexOf(state.tab),j=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:-1)+4)%4;state.tab=tabs[j];updateDetail();$(`#galaxy-tab-${state.tab}`).focus();}},{signal});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('.modal')){if(state.expanded){e.preventDefault();expanded();}else stopTour();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement).tagName)){e.preventDefault();state.railOpen=true;root.classList.remove('rail-closed');root.querySelector<HTMLInputElement>('#galaxy-search')?.focus();}},{signal});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour();},{signal});
 void init();
 return()=>{disposed=true;clearExports();stopTour();clearTimeout(searchTimer);scene?.destroy();abort.abort();document.body.classList.remove('galaxy-fullscreen');document.querySelectorAll<HTMLElement>('.topbar').forEach(x=>x.inert=false);};
}
